package hu.boltseged.shipment;
import jakarta.persistence.*; import java.math.BigDecimal; import java.util.UUID;
@Entity @Table(name="shipment_packages") public class ShipmentPackage { @Id private UUID id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="shipment_id",nullable=false) private Shipment shipment; private int packageIndex; private String trackingNumber; private BigDecimal weight,length,width,height; protected ShipmentPackage(){} ShipmentPackage(Shipment s,int i,Shipment.PackageInput p){id=UUID.randomUUID();shipment=s;packageIndex=i;weight=p.weight();length=p.length();width=p.width();height=p.height();} public String getTrackingNumber(){return trackingNumber;} public int getPackageIndex(){return packageIndex;} public UUID getId(){return id;} public BigDecimal getWeight(){return weight;} public BigDecimal getLength(){return length;} public BigDecimal getWidth(){return width;} public BigDecimal getHeight(){return height;} void setTrackingNumber(String value){trackingNumber=value;} }
